script:
frappe.ui.form.on('Stock Entry', {
    'items': {
        item_code: function(frm, cdt, cdn) {
            console.log('🔍 Evento item_code disparado', cdt, cdn);
            // Cuando cambia el item_code en la tabla items
            let row = locals[cdt][cdn];
            console.log('📦 Row data:', row.item_code, 'Barcode actual:', row.barcode);

            if (row.item_code && !row.barcode) {
                console.log('🔎 Buscando barcode para:', row.item_code);
                // Buscar directamente el barcode en Item Barcode
                frappe.call({
                    method: 'frappe.client.get_list',
                    args: {
                        doctype: 'Item Barcode',
                        filters: {
                            parent: row.item_code
                        },
                        fields: ['barcode'],
                        limit: 1
                    },
                    callback: function(bc_r) {
                        console.log('📋 Respuesta barcode:', bc_r);
                        if (bc_r.message && bc_r.message.length > 0 && bc_r.message[0].barcode) {
                            console.log('✅ Seteando barcode:', bc_r.message[0].barcode);
                            frappe.model.set_value(cdt, cdn, 'barcode', bc_r.message[0].barcode);
                        } else {
                            console.log('⚠️ No se encontró barcode');
                        }
                    }
                });
            } else {
                console.log('⏭️ Saltando: item_code vacío o barcode ya existe');
            }
        }
    }
});

frappe.ui.form.on('Stock Entry Detail', {
    item_code: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (row.item_code) {
            // Obtener el código de barras del item
            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'Item Barcode',
                    filters: {
                        parent: row.item_code
                    },
                    fields: ['barcode'],
                    limit: 1
                },
                callback: function(bc_r) {
                    if (bc_r.message && bc_r.message.length > 0 && bc_r.message[0].barcode) {
                        // Acceder directamente al row y setear el valor
                        let row_obj = locals[cdt][cdn];
                        row_obj.barcode = bc_r.message[0].barcode;
                        // Refrescar el campo
                        frm.refresh_field('items');
                    }
                }
            });
        }
    }
});

frappe.ui.form.on('Sales Invoice', {
    custom_receta_medica: function(frm) {
        if (frm.doc.custom_receta_medica && !frm.doc.__islocal) {
            // Solo agregar items si el documento ya está guardado
            // y hay una receta asociada
            frappe.confirm(
                __('¿Desea agregar todos los medicamentos de la receta {0} a esta venta?', [frm.doc.custom_receta_medica]),
                function() {
                    // Usuario confirmó
                    frappe.call({
                        method: 'barriofarma_app.barriofarma_app.api.receta_medica.add_receta_medica_items_to_invoice_api',
                        args: {
                            invoice_name: frm.doc.name,
                            receta_name: frm.doc.custom_receta_medica,
                            warehouse: frm.doc.set_warehouse
                        },
                        callback: function(r) {
                            if (r.message) {
                                let msg = __('Se agregaron {0} medicamentos de la receta.', [r.message.items_added.length]);
                                if (r.message.items_skipped.length > 0) {
                                    msg += ' ' + __('{0} medicamentos ya estaban en la venta.', [r.message.items_skipped.length]);
                                }
                                frappe.show_alert({
                                    message: msg,
                                    indicator: 'green'
                                }, 5);
                                frm.reload_doc();
                            }
                        }
                    });
                },
                function() {
                    // Usuario canceló
                }
            );
        }
    }
});

// Story 6.2: Alertas de Productos Próximos a Caducar
// Indicadores visuales en listado de productos

frappe.listview_settings['Item'] = {
    get_indicator: function(doc) {
        // Solo mostrar indicador si el item usa batches
        if (!doc.has_batch_no) {
            return [];
        }

        // Verificar si ya tenemos el estado de caducidad en caché
        if (doc._expiry_status) {
            return doc._expiry_status;
        }

        // Obtener estado de caducidad del item de forma asíncrona
        // Por ahora retornamos vacío, el indicador se actualizará cuando se cargue
        frappe.call({
            method: 'barriofarma_app.barriofarma_app.api.expiry_alerts.get_item_expiry_status',
            args: {
                item_code: doc.name
            },
            callback: function(r) {
                if (r.message && r.message.success && r.message.data) {
                    let status = r.message.data.status;
                    let min_days = r.message.data.min_days_to_expiry;

                    if (min_days !== null && status !== 'ok') {
                        let color = 'blue';
                        let label = __('Caduca en {0} días', [min_days]);

                        if (status === 'critical') {
                            color = 'red';
                            label = __('⚠️ Caduca en {0} días', [min_days]);
                        } else if (status === 'warning') {
                            color = 'orange';
                            label = __('⚡ Caduca en {0} días', [min_days]);
                        } else if (status === 'info') {
                            color = 'blue';
                            label = __('ℹ️ Caduca en {0} días', [min_days]);
                        }

                        // Guardar en caché
                        doc._expiry_status = [label, color, 'expiry_date,<,' + min_days];

                        // Refrescar el listado para mostrar el indicador
                        if (cur_list) {
                            cur_list.refresh();
                        }
                    }
                }
            }
        });

        return [];
    }
};
